function login(b) {
  if (b == undefined) return true;
  info = result
  so = getUrl();
  pw = info.密码

  if (b) {
    url = so + '/index/login,'
    body = `email=${info.邮箱}&pass=${pw}`
  }  
   post = JSON.stringify({
    "body": String(body),
    "method": "POST"
  })
  url += post
  result = java.ajax(url)
  java.log(result)
  if (result.match(/data/)){
  	  	  java.toast('\n'+info["邮箱"]+'登录成功')
  java.log(url)
  }
  c = cookie.getCookie(getUrl());
  source.putLoginHeader(c);
  }
