    url: "/api/cate/," + JSON.stringify({
        "body": "{\"page\":{\"page\":{{page}},\"pageSize\":36},\"category\":\"video\",\"sort\":0,\"comic\":{\"status\":-1,\"day\":0,\"year\":0,\"tag\":\"\"},\"video\":{\"typeId\":" + typeId + ",\"tag\":\"" + tag + "\",\"area\":\"\",\"lang\":\"\",\"status\":-1,\"year\":0},\"novel\":{\"status\":-1,\"day\":0,\"sortId\":0}}",
        "method": "POST"
    }),
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: size
    }
});

// typeId名称映射
var types = ["", "国产", "日韩", "欧美", "港台", "电影", "里番"];
// 全部tag列表（含空=全部）
var tags = ["全部", "动画", "喜剧", "奇幻", "剧情", "冒险", "动作", "科幻", "爱情", "儿童", "短片", "家庭", "悬疑", "运动"];

for (var t = 1; t <= 6; t++) {
    for (var g = 0; g < tags.length; g++) {
        var title = types[t] + '-' + tags[g];
        var tag = (g === 0) ? '' : tags[g];
        var size = (g === 0) ? 1 : 0.25;
        push(title, t, tag, size);
    }
}

JSON.stringify(result);

